import json
from typing import Optional
from .base import AHBaseReportInfo
from .protocols import AHReportType, AHHTTPMethod, AHReportError


class AHLogReport:
    report_type = AHReportType.LOG
    http_method = AHHTTPMethod.POST

    def __init__(self, base_info: AHBaseReportInfo, message: str, sub_type: str,
                 log_type: str = '800000', user_defined: Optional[dict] = None):
        self.base_info = base_info
        self.message = message
        self.sub_type = sub_type
        self.log_type = log_type
        self.user_defined = user_defined
        self.base_url = self.report_type.base_url()
        self.endpoint = self.report_type.endpoint()

    def parameters(self) -> dict:
        user_defined_str = ''
        if self.user_defined:
            try:
                user_defined_str = json.dumps(self.user_defined)
            except Exception:
                pass
        return {
            'app_version': self.base_info.app_version,
            'app_id': self.base_info.app_id,
            'code_log_message': self.message,
            'code_log_sub_type': self.sub_type,
            'code_log_type': self.log_type,
            'user_agent': self.base_info.user_agent,
            'user_defined': user_defined_str,
            'user_id': self.base_info.username,
        }

    def validate(self):
        if not self.message or not self.message.strip():
            raise AHReportError.validation_failed('Message cannot be empty')
        if not self.sub_type or not self.sub_type.strip():
            raise AHReportError.validation_failed('SubType cannot be empty')


class AHAlertType:
    IDE_MCP_CALL = 'IDE_MCP_CALL'
    MCP_SERVICE = 'MCP_SERVICE'
    PACKAGE_REPLACE = 'PACKAGE_REPLACE'
    API_REQUEST = 'API_REQUEST'


class AHAlertStatus:
    SUCCESS = 'SUCCESS'
    FAILED = 'FAILED'
    TIMEOUT = 'TIMEOUT'
    ERROR = 'ERROR'


class AHAlertLevel:
    INFO = 'INFO'
    WARNING = 'WARNING'
    ERROR = 'ERROR'
    CRITICAL = 'CRITICAL'


class AHAlertReport:
    report_type = AHReportType.ALERT
    http_method = AHHTTPMethod.POST

    def __init__(self, base_info: AHBaseReportInfo, alert_type: str, status: str, title: str,
                 alert_message: Optional[str] = None, alert_level: Optional[str] = None,
                 service_name: Optional[str] = None, request_id: Optional[str] = None,
                 ide_type: Optional[str] = None, mcp_version: Optional[str] = None,
                 api_url: Optional[str] = None, response_time: Optional[float] = None,
                 error_code: Optional[str] = None, ext_data: Optional[dict] = None):
        self.base_info = base_info
        self.alert_type = alert_type
        self.status = status
        self.title = title
        self.alert_message = alert_message
        self.alert_level = alert_level
        self.service_name = service_name
        self.request_id = request_id
        self.ide_type = ide_type
        self.mcp_version = mcp_version
        self.api_url = api_url
        self.response_time = response_time
        self.error_code = error_code
        self.ext_data = ext_data
        self.base_url = self.report_type.base_url()
        self.endpoint = self.report_type.endpoint()

    def parameters(self) -> dict:
        return {
            'alert_type': self.alert_type,
            'status': self.status,
            'title': self.title,
            'username': self.base_info.username,
            'message': self.alert_message,
            'alert_level': self.alert_level,
            'service_name': self.service_name,
            'request_id': self.request_id,
            'ide_type': self.ide_type,
            'ide_version': self.base_info.app_version,
            'mcp_version': self.mcp_version,
            'api_url': self.api_url,
            'response_time': self.response_time,
            'error_code': self.error_code,
            'ext_data': self.ext_data,
        }

    def validate(self):
        if not self.title or not self.title.strip():
            raise AHReportError.validation_failed('Title cannot be empty')


class AHAdoptionReport:
    report_type = AHReportType.ADOPTION
    http_method = AHHTTPMethod.POST

    def __init__(self, base_info: AHBaseReportInfo, is_accepted: bool, accept_code: str,
                 file_path: str, repository_url: str, prompt_count: int,
                 ide_type: int, ask_type: int, ext: Optional[dict] = None):
        self.base_info = base_info
        self.is_accepted = is_accepted
        self.accept_code = accept_code
        self.file_path = file_path
        self.repository_url = repository_url
        self.prompt_count = prompt_count
        self.ide_type = ide_type
        self.ask_type = ask_type
        self.ext = ext
        self.base_url = self.report_type.base_url()
        self.endpoint = self.report_type.endpoint()

    def parameters(self) -> dict:
        email = f'{self.base_info.username}@autohome.com.cn'
        line_count = len(self.accept_code.splitlines())
        ext_str = ''
        try:
            # 允许 hook 侧只上报新增行数，不上传代码/diff 内容。
            if isinstance(self.ext, dict) and isinstance(self.ext.get('accept_line_count'), int):
                line_count = max(0, self.ext.get('accept_line_count'))
            ext_str = json.dumps(self.ext)
        except Exception:
            pass
        return {
            'username': self.base_info.username,
            'mail': email,
            'prompt_count': self.prompt_count,
            'accept_count': 1 if self.is_accepted else 0,
            'accept_line_count': line_count if self.is_accepted else 0,
            'accept_code': self.accept_code,
            'file_path': self.file_path,
            'repository_url': self.repository_url,
            'idetype': self.ide_type,
            'ext': ext_str,
            'ask_type': self.ask_type,
            'ide_version': self.base_info.app_version,
        }

    def validate(self):
        pass
